file: mem0/vector_stores/neptune_analytics.py
name: query_string
placeholders: ['top_k', 'vectors', 'filter_clause']
---

            CALL neptune.algo.vectors.topKByEmbeddingWithFiltering({{
                    topK: {top_k},
                    embedding: {vectors}
                    {filter_clause}
                  }}
                )
            YIELD node, score
            RETURN node as n, score
